// STAGE 1: Input Parser (v2 - URLs no longer needed)
// Extracts category + optional focus from chat input.
const input = $input.first().json.chatInput || '';

const categories = [
  { key: 'area_rug', display: 'Area Rug', patterns: ['area rug', 'area rugs'] },
  { key: 'outdoor_rug', display: 'Outdoor Rug', patterns: ['outdoor rug', 'outdoor rugs', 'patio rug'] },
  { key: 'hallway_runner', display: 'Hallway Runner', patterns: ['hallway runner', 'runner rug', 'hall runner', 'runners'] },
  { key: 'shag_rug', display: 'Shag Rug', patterns: ['shag rug', 'shag rugs', 'shaggy rug'] },
];

let selectedCategory = null;
let categoryKey = null;
const lowerInput = input.toLowerCase();

for (const cat of categories) {
  for (const pattern of cat.patterns) {
    if (lowerInput.includes(pattern)) {
      selectedCategory = cat.display;
      categoryKey = cat.key;
      break;
    }
  }
  if (selectedCategory) break;
}

const focusMatch = input.match(/focus\s*:\s*([^\n]+)/i);
const focus = focusMatch ? focusMatch[1].trim() : '';
const hasCategory = Boolean(selectedCategory);
const hasValidInput = hasCategory;

return [{
  json: {
    selectedCategory,
    categoryKey,
    focus,
    hasCategory,
    hasValidInput,
    errorReason: hasCategory ? null : 'no_category',
  },
}];

// Error response - handles multiple failure modes
const input = $input.first().json;
const reason = input.errorReason || 'unknown';

let errorMsg;
if (reason === 'no_category') {
  errorMsg = 'I could not detect a category. Please include one of:\n- Area Rug\n- Outdoor Rug\n- Hallway Runner\n- Shag Rug\n\n**Example input:**\nArea Rug\nfocus: washable';
} else if (reason === 'no_products') {
  errorMsg = 'No products were returned for this category. The pre-scraped dataset may not have refreshed yet, or the program API may be temporarily unavailable. Try again in a few minutes, or contact the program team if this persists.';
} else {
  errorMsg = 'An unknown error occurred. Please try again or contact the program team.';
}

return [{ json: { error: true, message: errorMsg, reason } }];

// Reshape FastAPI response to the { amazonProducts } shape
// expected by the downstream market-intelligence pipeline.
const r = $input.first().json;
const products = r.products || [];

return [{
  json: {
    amazonProducts: products.map((p) => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// Stage 2B: expose the normalized category for all social-signal API calls.
const parsed = $('Input Parser1').first().json;
return [{ json: {
  categoryKey: parsed.categoryKey || 'area_rug',
  selectedCategory: parsed.selectedCategory || 'Area Rug',
  focus: parsed.focus || ''
} }];

// Merge and normalize social/industry signals while keeping market research separate.
const safe = (name) => { try { return $(name).first().json || { items: [] }; } catch { return { items: [] }; } };
const instagram = safe('Fetch Instagram');
const pinterest = safe('Fetch Pinterest');
const blogs = safe('Fetch Blogs');
const market = safe('Fetch Market Data');

const extractImages = (items, source, limit = 3) => (items || [])
  .filter(item => item.image_base64)
  .slice(0, limit)
  .map(item => ({ source, id: item.id, url: item.url, caption: item.caption || '', image_base64: item.image_base64, mime_type: item.image_mime_type || 'image/jpeg' }));

const socialImages = [
  ...extractImages(instagram.items, 'instagram'),
  ...extractImages(pinterest.items, 'pinterest')
];

return [{ json: {
  category: $('Get Category Key').first().json,
  socialData: { instagram: instagram.items || [], pinterest: pinterest.items || [], blogs: blogs.items || [] },
  marketData: market.items || [],
  socialImages,
  totalSocialItems: (instagram.items?.length || 0) + (pinterest.items?.length || 0) + (blogs.items?.length || 0),
  totalMarketItems: market.items?.length || 0,
  totalSocialImages: socialImages.length,
  externApiStatus: {
    instagram: instagram.items?.length ? 'success' : 'empty_or_failed',
    pinterest: pinterest.items?.length ? 'success' : 'empty_or_failed',
    blogs: blogs.items?.length ? 'success' : 'empty_or_failed',
    market: market.items?.length ? 'success' : 'empty_or_failed'
  }
} }];

// Convert captions, hashtags and engagement into structured visual-trend signals.
const merged = $('Merge Social Data1').first().json;
const instagram = merged.socialData?.instagram || [];
const pinterest = merged.socialData?.pinterest || [];
const insights = [
  ...instagram.map(post => ({ source: 'instagram', url: post.url, caption: post.caption || '', hashtags: post.hashtags || [], engagement: post.engagement || 0, postedAt: post.posted_at || null })),
  ...pinterest.map(pin => ({ source: 'pinterest', url: pin.url, caption: pin.caption || '', hashtags: pin.hashtags || [], engagement: pin.engagement || 0, postedAt: pin.posted_at || null }))
];
const hashtagCounts = {};
for (const tag of insights.flatMap(item => item.hashtags)) hashtagCounts[tag] = (hashtagCounts[tag] || 0) + 1;
const topHashtags = Object.entries(hashtagCounts).sort((a,b) => b[1]-a[1]).slice(0,20).map(([tag,count]) => ({ tag, count }));

return [{ json: {
  category: merged.category,
  imageAnalysis: { trend_summary: {
    top_hashtags: topHashtags,
    total_posts_analyzed: insights.length,
    instagram_count: instagram.length,
    pinterest_count: pinterest.length,
    caption_insights: insights.map(x => x.caption).join(' ').substring(0, 2000)
  }, source: 'social_captions_hashtags_and_engagement' },
  socialInsights: insights,
  socialImages: merged.socialImages || [],
  socialData: merged.socialData,
  marketData: merged.marketData || [],
  totals: { socialItems: merged.totalSocialItems, marketItems: merged.totalMarketItems, images: merged.totalSocialImages },
  externApiStatus: merged.externApiStatus,
  analysisSuccess: true,
  reason: 'Social captions, hashtags and engagement normalized for downstream trend segmentation'
} }];

